function rollSeasonInjury(chance) {
  if (Math.random() >= chance) return null;
  const sev = Math.random();
  if (sev < 0.15) return { name: pick(INJ_SEVERE), weeks: rand(14, 30), severe: true };
  if (sev < 0.5) return { name: pick(INJ_MODERATE), weeks: rand(5, 10), severe: false };
  return { name: pick(INJ_MINOR), weeks: rand(2, 4), severe: false };
}
var BDOR_WIN_MIN_GOALS = 30;
function rollPotential(startingOvr) {
  const r = Math.random();
  let pot;
  if (r < 0.5) pot = rand(70, 79);
  else if (r < 0.8) pot = rand(78, 84);
  else if (r < 0.93) pot = rand(84, 89);
  else if (r < 0.985) pot = rand(89, 93);
  else pot = rand(93, 97);
  return Math.min(99, Math.max(pot, startingOvr + 6));
}
