function mlbFullSlate(pos3) {
  if (pos3 === "SP") return 30;
  if (pos3 === "RP") return 60;
  return 150;
}
function mlbSlateMark(pos3, mark, line) {
  const slate = slateOf("mlb", line);
  return toSlate("mlb", mark, mlbWorkSlate(pos3, slate));
}
function mlbBadgeFacts(c) {
  const t = mlbCareerTotals(c);
  let saves = 0;
  for (const s2 of c.seasons) saves += s2.saves ?? 0;
  const slate = mlbFullSlate(c.pos);
  return {
    pos: c.pos,
    /* Round 1226: a badge that asks for a full year (120 games for the .330
       season, 20 starts for the sub 2.00 one) reads a season's games as the
       full season they stand for, so all 60 games of 2020 count as one. A
       line with no slate is read as it always was. */
    seasons: c.seasons.map((s2) => ({
      games: fullSeasonOf("mlb", s2.games, mlbWorkSlate(c.pos, slateOf("mlb", s2))),
      awards: s2.awards ?? [],
      teamResult: s2.teamResult,
      avg: s2.avg,
      hr: s2.hr,
      sb: s2.sb,
      era: s2.era
    })),
    rings: c.rings,
    mvpCys: c.mvpCys,
    allStars: c.allStars,
    totals: { hr: t.hr, rbi: t.rbi, sb: t.sb, wins: t.wins, so: t.so, saves },
    fullSeasons: c.seasons.filter((s2) => s2.games >= mlbSlateMark(c.pos, slate, s2)).length,
    wealth: Math.round(((c.netWorth ?? 0) + mlbMoneyWealth(c)) * 100) / 100,
    retired: c.retired,
    hof: c.retired && mlbLegacyOf(c).hof,
    rival: c.rival ? { retired: c.rival.retired, myYears: c.rival.myYears, hisYears: c.rival.hisYears } : null
  };
}
function mlbEarnedBadges(c) {
  return earnedBadges(MLB_BADGES, mlbBadgeFacts(c));
}
function mlbFollowers(c) {
  return followersFromFanbase({
    fanbase: c.fanbase,
    seasons: c.seasons.length,
    rings: c.rings,
    awards: c.mvpCys + c.allStars
  });
}
function mlbFanComments(c) {
  return fanComments("mlb", {
    pos: c.pos,
    standing: c.fanbase,
    followers: fmtFollowers(mlbFollowers(c)),
    conduct: conductOnRecord(c)
  });
}
function mlbHeadlinesFor(c, line) {
  const slate = mlbSlateMark(c.pos, c.pos === "SP" ? 32 : c.pos === "RP" ? 62 : US_ENGINE_SEASON.mlb - 7, line);
  return mlbSeasonHeadlines({
    name: c.name,
    team: mlbTeamLabelOf(line.team, c.eraId),
    pos: c.pos,
    line,
    /* A bench bat and a long relief arm are given fewer games on purpose
       (Round 183), so their gap says nothing about health and is not
       reported as an injury. */
    missed: line.teamResult === "SUSPENDED" || c.role === "backup" && c.pos !== "RP" ? 0 : Math.max(0, slate - line.games),
    role: c.role
  });
}

