// src/lib/nhlCareerMoney.ts
init_define_import_meta_env();
init_careerMoney();
var clamp45 = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
var NHL_MONEY = {
  currency: "$",
  seedOf: (c) => seedFromName(c.name, c.seasons?.length ?? 0),
  yearOf: (c) => c.seasons.length > 0 ? c.seasons[c.seasons.length - 1].year : c.year,
  billOf: (c) => c.yearlyCosts ?? 0,
  shame: (c) => {
    c.fanbase = clamp45(c.fanbase - 2, 0, 100);
  },
  words: {
    cards: {
      ledger: "Cards at the back of the plane",
      crew: "the boys",
      crewCap: "The boys",
      where: "at the back of the plane",
      thatPlace: "in that card game",
      next: "Next road swing."
    },
    arcade: { ledger: "Won the phone quiz", name: "the ball quiz" }
  }
};
function nhlMoneyWealth(c) {
  return moneyWealth(c, NHL_MONEY);
}
function nhlMoneySeasonTick(c) {
  return moneySeasonTick(c, NHL_MONEY.yearOf(c), NHL_MONEY);
}
function nhlMoneyAct(c, action) {
  return moneyAct(c, action, NHL_MONEY);
}

