var NHL_INBOX = {
  pool: NHL_INBOX_POOL,
  moodOf: (c) => c.karma ?? 50,
  setMood: (c, v) => {
    c.karma = v;
  },
  addPopularity: (c, delta) => {
    c.fanbase = clamp46(c.fanbase + delta, 0, 100);
  },
  addCash: (c, amount) => {
    c.netWorth = Math.round(((c.netWorth ?? 0) + amount) * 10) / 10;
  },
  ageOf: (c) => c.age,
  yearOf: (c) => c.seasons.length > 0 ? c.seasons[c.seasons.length - 1].year : c.year,
  maxInbox: 6,
  wantPerSeason: 3,
  calendar: NHL_CALENDAR
};
function nhlSeasonBeats(c) {
  const line = c.seasons[c.seasons.length - 1];
  if (!line || line.teamResult === "SUSPENDED") return ["offseason"];
  const beats = ["camp"];
  if (line.age <= 19) beats.push("juniors");
  beats.push("allstar", "deadline");
  if ((line.poGames ?? 0) > 0) beats.push("playoffs");
  beats.push("offseason");
  if (!c.retired && c.contractYears === 1) beats.push("contract");
  return beats;
}
function receiveNhlInboxTexts(c, goesOn = true, rng) {
  return receiveCalendarInboxTexts(c, "pro", NHL_INBOX, rng ?? inboxStream(c, "season"), nhlSeasonBeats(c), goesOn && !c.retired);
}
function nhlDraftNightInbox(c, rng) {
  return deliverInboxTexts(c, "pro", NHL_INBOX, rng ?? inboxStream(c, "draft"), ["draft"]);
}
function nhlUnreadInboxCount(c) {
  return unreadInboxCount(c);
}
function answerNhlInboxMessage(c, msgId, choiceIdx) {
  return answerInboxMessage(c, msgId, choiceIdx, NHL_INBOX);
}

