function nhlFullSlate(pos3) {
  return pos3 === "G" ? 55 : US_ENGINE_SEASON.nhl - 4;
}
function nhlFullSlateOf(pos3, line) {
  return toSlate("nhl", nhlFullSlate(pos3), nhlWorkSlate(pos3, slateOf("nhl", line)));
}
function nhlBadgeFacts(c) {
  const t = nhlCareerTotals(c);
  return {
    pos: c.pos,
    /* Round 1226: the .930 season asks for 40 games in the crease, a full
       year's worth. A season's games are read as the full season they stand
       for, so a goalie's 36 starts of the 48 game 2012-13 count as one. A
       line with no slate is read as it always was. */
    seasons: c.seasons.map((s2) => ({
      games: fullSeasonOf("nhl", s2.games, nhlWorkSlate(c.pos, slateOf("nhl", s2))),
      awards: s2.awards ?? [],
      teamResult: s2.teamResult,
      goals: s2.goals,
      points: s2.points,
      wins: s2.wins,
      svpct: s2.svpct
    })),
    cups: c.cups,
    harts: c.harts,
    connSmythes: c.connSmythes,
    allStars: c.allStars,
    totals: { goals: t.goals, assists: t.assists, points: t.points, wins: t.wins },
    fullSeasons: c.seasons.filter((s2) => s2.games >= nhlFullSlateOf(c.pos, s2)).length,
    wealth: Math.round(((c.netWorth ?? 0) + nhlMoneyWealth(c)) * 100) / 100,
    retired: c.retired,
    hof: c.retired && nhlLegacyOf(c).hof,
    rival: c.rival ? { retired: c.rival.retired, myYears: c.rival.myYears, hisYears: c.rival.hisYears } : null
  };
}
function nhlEarnedBadges(c) {
  return earnedBadges(NHL_BADGES, nhlBadgeFacts(c));
}
function nhlFollowers(c) {
  return followersFromFanbase({
    fanbase: c.fanbase,
    seasons: c.seasons.length,
    rings: c.cups,
    awards: c.harts + c.allStars + c.connSmythes
  });
}
function nhlFanComments(c) {
  return fanComments("nhl", {
    pos: c.pos,
    standing: c.fanbase,
    followers: fmtFollowers(nhlFollowers(c)),
    conduct: conductOnRecord(c)
  });
}
function nhlHeadlinesFor(c, line) {
  const held = nhlWorkSlate(c.pos, slateOf("nhl", line));
  const slate = c.pos === "G" ? toSlate("nhl", 58, held) : held;
  return nhlSeasonHeadlines({
    name: c.name,
    team: nhlTeamLabelOf(line.team, c.eraId),
    pos: c.pos,
    line,
    /* A backup goalie's starts and a fourth liner's minutes are the role
       (Round 183), not a knock, so their gap is not reported as an injury. */
    missed: line.teamResult === "SUSPENDED" || c.role === "backup" ? 0 : Math.max(0, slate - line.games),
    role: c.role
  });
}

